// Shape each order and find the newest updated_at in this page.
const rows = $input.all().map(i => i.json);
let maxCursor = '1970-01-01T00:00:00Z';
const out = rows.map(o => {
  if (o.updated_at && o.updated_at > maxCursor) maxCursor = o.updated_at;
  return { order_id: String(o.id), email: o.email, total: Number(o.total_price||0), currency: o.currency, financial_status: o.financial_status, created_at: o.created_at, updated_at: o.updated_at };
});
return out.map(r => ({ json: { ...r, _maxCursor: maxCursor, _pageSize: out.length } }));

